    s=open(MS+name+".tpl.md").read(); 
    for _ in range(3): s=re.sub(r"\[\[(\w+)\]\]",lambda m: str(K[m.group(1)]) if m.group(1) in K else m.group(0),s)
    left=sorted(set(re.findall(r"\[\[(\w+)\]\]",s))); open(MS+name+".md","w").write(s); print(name,"filled; unresolved:",left)
